  const parentId=root?null:node.id
  const children=world.nodes.filter(n=>n.parentId===parentId)
  const addCollection=()=>ask('集合名称','新集合',name=>onChange({...world,nodes:[...world.nodes,{id:uid(),name,type:'collection',parentId}]}))
  const deleteCollection=()=>{if(root||node.protected||!confirm(`删除集合“${node.name}”？内部对象将移至上级集合。`))return;onChange(removeCollection(world,node.id));onSelect({nodeId:node.parentId||world.id})}
