export function ViewConfig({kind,world,onChange}:{kind:'map'|'chat';world:World;onChange:(w:World)=>void}){
  return <div className="page-scroll"><div className="page-heading ui-page-toolbar ui-page-toolbar--page"><div><div className="eyebrow">VIEW CONFIG</div><h1>{kind==='map'?'地图配置':'聊天框配置'}</h1><p>保存界面资源与接入选项，功能接口将在后续版本启用。</p></div></div><div className="schema-panel ui-panel--schema config-form ui-surface ui-panel ui-panel--themed ui-panel--text">{kind==='map'?<><label>地图文件<input value={world.map.image} placeholder="地图图片路径" onChange={e=>onChange({...world,map:{...world.map,image:e.target.value}})} className="ui-surface ui-field"/></label><label>图例配置<textarea value={world.map.legend} placeholder="输入图例说明" onChange={e=>onChange({...world,map:{...world.map,legend:e.target.value}})} className="ui-surface ui-field"/></label></>:<><label>Agent<input value={world.chat.agent} placeholder="Agent 名称或标识" onChange={e=>onChange({...world,chat:{...world.chat,agent:e.target.value}})} className="ui-surface ui-field"/></label><label>接入文件<input value={world.chat.files.join(', ')} placeholder="以逗号分隔文件名" onChange={e=>onChange({...world,chat:{...world.chat,files:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)}})} className="ui-surface ui-field"/></label><label>接入 Skill<input value={world.chat.skills.join(', ')} placeholder="以逗号分隔 Skill 名称" onChange={e=>onChange({...world,chat:{...world.chat,skills:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)}})} className="ui-surface ui-field"/></label></>}</div></div>
}



